def minPath(grid, k):
    n = len(grid)
    # Find position of 1
    r1, c1 = 0, 0
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                r1, c1 = i, j
    # Find minimum neighbor of cell 1
    min_neighbor = n * n + 1
    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
        nr, nc = r1 + dr, c1 + dc
        if 0 <= nr < n and 0 <= nc < n:
            min_neighbor = min(min_neighbor, grid[nr][nc])
    # Build result: alternating 1 and min_neighbor
    result = []
    for i in range(k):
        if i % 2 == 0:
            result.append(1)
        else:
            result.append(min_neighbor)
    return result

